class Account:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        if amount < 0:
            raise ValueError("Amount must be non-negative")
        self.balance += amount
        return self.balance

    def withdraw(self, amount):
        if amount < 0:
            raise ValueError("Amount must be non-negative")
        if self.balance < amount:
            raise ValueError("Insufficient funds")
        self.balance -= amount
        return self.balance

