def slugify(text):
    text = text.lower()
    text = ''.join(c for c in text if not c.isalnum() or c == ' ')
    parts = text.split()
    result = []
    prev_is_dash = False
    for part in parts:
        if not part:
            continue
        is_dash = any(c == '-' for c in part)
        if is_dash and prev_is_dash:
            continue
        result.append(part.replace('-', ''))
        prev_is_dash = is_dash
    return '-'.join(result)

def slugify(text):
    text = text.lower()
    text = ''.join(c for c in text if c.isalnum() or c == ' ')
    parts = text.split()
    result = []
    for part in parts:
        result.append(part.replace('-', '').replace('_', ''))
    return '-'.join(result).strip('-')

