def mean(xs):
    return sum(xs) / len(xs)


def median(xs):
    xs = sorted(xs)
    if not xs:
        raise ValueError('empty list')
    n = len(xs)
    return (xs[n // 2 - 1] + xs[n // 2]) / 2 if n % 2 == 0 else xs[n // 2]


def mode(xs):
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    max_count = max(counts.values())
    # Sort the keys by value and then by key to get the smallest in case of a tie
    sorted_items = sorted(counts.items(), key=lambda item: (item[1], item[0]))
    # Return the key with the maximum count, and in case of a tie, the smallest key
    return [k for k, v in sorted_items if v == max_count][0]

