def mean(xs):
    return sum(xs) / len(xs)


def median(xs):
    if not xs:
        raise ValueError("median() arg is empty")
    xs = sorted(xs)
    n = len(xs)
    if n % 2 == 1:
        return xs[n // 2]
    else:
        return (xs[n // 2 - 1] + xs[n // 2]) / 2


def mode(xs):
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    max_count = max(counts.values())
    modes = [x for x, c in counts.items() if c == max_count]
    return min(modes)

